import{_ as a,H as i,f as t,i as p}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"12-DeFi的空中楼阁能盖多高？","description":"","frontmatter":{},"headers":[{"level":2,"title":"DeFi 领域里值得关注的两个问题","slug":"defi-领域里值得关注的两个问题","link":"#defi-领域里值得关注的两个问题","children":[]},{"level":2,"title":"抵押借贷的系统性风险","slug":"抵押借贷的系统性风险","link":"#抵押借贷的系统性风险","children":[{"level":3,"title":"流动池锁仓量可以引发蝴蝶效应","slug":"流动池锁仓量可以引发蝴蝶效应","link":"#流动池锁仓量可以引发蝴蝶效应","children":[]},{"level":3,"title":"稳定币基本面的重要性","slug":"稳定币基本面的重要性","link":"#稳定币基本面的重要性","children":[]}]},{"level":2,"title":"流动性挖矿的风险","slug":"流动性挖矿的风险","link":"#流动性挖矿的风险","children":[{"level":3,"title":"流动性挖矿的收益风险问题","slug":"流动性挖矿的收益风险问题","link":"#流动性挖矿的收益风险问题","children":[]},{"level":3,"title":"为争夺流动性挖矿奖励产生的多层嵌套问题","slug":"为争夺流动性挖矿奖励产生的多层嵌套问题","link":"#为争夺流动性挖矿奖励产生的多层嵌套问题","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Web3.0入局攻略/12-DeFi的空中楼阁能盖多高？.md","filePath":"Web3.0入局攻略/12-DeFi的空中楼阁能盖多高？.md","lastUpdated":1795535932000}'),r={name:"Web3.0入局攻略/12-DeFi的空中楼阁能盖多高？.md"};function l(n,e,o,s,A,E){return i(),t("div",null,[...e[0]||(e[0]=[p('<h1 id="_12-defi的空中楼阁能盖多高" tabindex="-1">12-DeFi的空中楼阁能盖多高？ <a class="header-anchor" href="#_12-defi的空中楼阁能盖多高" aria-label="Permalink to &quot;12-DeFi的空中楼阁能盖多高？&quot;">​</a></h1><p>你好，我是郭大治。</p><p>通过前面课程的学习，现在，我们已经清楚了为什么需要 Web 3.0，也结合 Web 3.0 的分层架构，了解了作为通用基础设施的计算层、身份层和激励层分别是什么，另外我还重点讲了Web 3.0 应用层的各个细分领域，比如 NFT、游戏、音乐、社交、金融和 DAO 等。那在接下来的课程中，我们会开启一个全新的视角，一起来看看 Web 3.0 生态主要都面临了哪些风险。</p><p>毕竟，没有零成本的创新，只有把创新和风险防范结合起来才有可能实现真正的创新。站在个人的视角，我们更要综合考虑风险和收益。</p><p>在刚刚过去的上半年，百亿市值的 LUNA 币在短短几天时间内的崩盘，让太多的用户付出了惨痛的代价；曾经风光一时的三箭资本也从市场宠儿走到了破产清算的地步。面对 Web3.0 这场已经开启的互联网革命，对于风险的认知一点也不应该比创新少。所以，希望通过这节课，能在你因为技术之光而被点燃的激情之中，注入一份理性的思考。</p><p>好了，下面我们正式开始。</p><h2 id="defi-领域里值得关注的两个问题" tabindex="-1">DeFi 领域里值得关注的两个问题 <a class="header-anchor" href="#defi-领域里值得关注的两个问题" aria-label="Permalink to &quot;DeFi 领域里值得关注的两个问题&quot;">​</a></h2><p>我们知道，Web 3.0 是一个基于底层技术重构，建立的涉及从技术到应用多个领域的综合型的生态。那么，关于风险的内容，同样也涉及从技术到应用，再到市场以及法律和伦理等多个层面，每个层面的风险都有不同的成因和表现，而这些因素又相互作用和影响，交织在一起，通过各种形式表现出来。</p><p>在接下来的这两节课中，我会重点选择和我们大多数用户最有可能发生交集的几个领域，也就是应用和法律的相关领域来进行分析，帮你建立一种关于 Web 3.0 相关风险的系统性认知，使你在独自面对一些具体问题的时候，能够根据这些系统性的认知，进行自我思考。</p><p>今天这节课，我们重点针对 DeFi 领域，来讲两个问题，一个是关于抵押借贷为整个 DeFi 生态带来的系统性风险问题，另一个是关于流动性挖矿的收益风险问题。</p><p>为什么要选择这两个问题呢？因为抵押借贷和流动性挖矿，是 DeFi 领域大多数用户参与度最高的两类业务，大多数用户往往会根据项目提供的年化收益率，来选择参与项目，但对于这两类业务背后的金融逻辑，以及它们分别蕴藏的风险，却并不具备十分清晰的认知。结果到最后，预期的高收益并没有获得，自己的本金还有可能造成较大的损失。</p><p>所以，我们就先从这两个问题讲起。</p><h2 id="抵押借贷的系统性风险" tabindex="-1">抵押借贷的系统性风险 <a class="header-anchor" href="#抵押借贷的系统性风险" aria-label="Permalink to &quot;抵押借贷的系统性风险&quot;">​</a></h2><p>关于这个问题，我们先来看一个案例。</p><p>尽管稳定币的核心命题是锚定目标价格，对冲价格波动，但一旦调节机制失灵，稳定币也会迅速“崩盘”。2022 年 5 月，LUNA 就给市场上演了一场活生生的“演示课”。</p><p>LUNA 是 Terra 协议的治理代币，Terra 是一条兼容 EVM（ETHEREUM VIRTUALMACHINE，以太坊虚拟机）且实现 Pos 共识机制的公链，所以 LUNA 的主要功能就是社区治理和支付 Gas 费。</p><p>Terra 团队同时还推出了一个锚定美元的稳定币项目 UST，并明确规定只有抵押 LUNA 才可以铸造（借出）UST。这种设计是抵押借贷的典型模式，比如像合成资产类项目 Synthetix，但不同的是考虑到代币价格的波动性比较强，Synthetix 将抵押率设置为 750%，这样抵押资产的价格风险传递到稳定币的可能性，就大大降低了。</p><p>但是 LUNA 没有进行这样的设计，而是将抵押率直接设定为 1，这样，抵押资产的价格风险将“不打折扣”地全部传递给稳定币。不仅如此，LUNA 还将 UST 的存款利率和 LUNA 的Staking 收益（质押挖矿）进行组合，通过 Anchor 平台向 UST 用户提供固定年化利率达20% 的存款产品。</p><p>这样的结果是，很多用户对于 LUNA 和 UST 的实际运行机制，其实并不是非常了解，但是对于固定年化 20% 的收益率却是非常“上头”，并因此而承担了巨大风险。</p><p>此外，Terra 也设计了套利机制，希望通过市场激励驱动 UST 价格锚定 1 美元。Terra 套利机制的主要设定是，1UST 始终能够兑换价值 1 美元的 LUNA，同时价值 1 美元的 LUNA 也能够兑换回 1UST。在 LUNA 价格相对稳定或者持续上升期间，这套机制对于 UST 锚定 1 美元确实发挥了一定的作用。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web3.0%E5%85%A5%E5%B1%80%E6%94%BB%E7%95%A5/images/12-DeFi%25E7%259A%2584%25E7%25A9%25BA%25E4%25B8%25AD%25E6%25A5%25BC%25E9%2598%2581%25E8%2583%25BD%25E7%259B%2596%25E5%25A4%259A%25E9%25AB%2598%25EF%25BC%259F/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web3.0%E5%85%A5%E5%B1%80%E6%94%BB%E7%95%A5/images/12-DeFi%25E7%259A%2584%25E7%25A9%25BA%25E4%25B8%25AD%25E6%25A5%25BC%25E9%2598%2581%25E8%2583%25BD%25E7%259B%2596%25E5%25A4%259A%25E9%25AB%2598%25EF%25BC%259F/1.png" alt=""></a></p><ul><li>LUNA和UST的关系</li></ul><p>图片来源于Cointelegraph</p><p>基于以上机制，2020 年 11 月 UST 从零起步，2022 年 5 月市值规模最高达到了 180 亿美元。在此期间，Terra 的管理团队为了降低 UST 抵押物的价格风险，分批次将作为抵押物的LUNA 部分调仓，买成 BTC 和 ETH，但 UST 和 LUNA 在机制设计上的漏洞却始终存在。</p><h3 id="流动池锁仓量可以引发蝴蝶效应" tabindex="-1">流动池锁仓量可以引发蝴蝶效应 <a class="header-anchor" href="#流动池锁仓量可以引发蝴蝶效应" aria-label="Permalink to &quot;流动池锁仓量可以引发蝴蝶效应&quot;">​</a></h3><p>时间来到了 2022 年 5 月，美联储加息预期，导致 BTC 以及整体加密资产价格快速下跌。终于，作为抵押资产的 LUNA 资产价值，低于了 UST 流通市值，这就使得 UST 从技术层面已经破产，这时候尽管市场还没有立即对此做出反应，但市场上做空 LUNA 和 UST 的力量已经开始聚集。</p><p>在此关键时刻，Terra 团队却似乎并没有感觉到市场形势的凶险，而且还在 5 月 8 日“不失时机”地为空头（Short/Bear）送上一次“绝佳的助攻”——项目方于 5 月 8 日开始，主动将Curve3 币池中的流动性撤回，并计划创造一个新的由 4 种稳定币构成的流动池。</p><p>我们知道，稳定币以价格稳定为首要目标，但在 DeFi 已经逐渐流行的今天，稳定币的价格并不是主要由中心化交易所主导的，而是通过 Curve 这样的 DEX（去中心化交易所）反映出来的。在 Curve 为 UST 和其他稳定币设置的流动池中，因为 UST 和一系列的稳定币都锚定美元，所以 UST 的数量应该等于其他稳定币的数量之和。而且，所有稳定币加总的锁仓量（Total Value Locked，TVL）越多，UST 的币值就越稳定。</p><p>因为流动池锁仓量对于 UST 的币价来说，就像是一条护城河，河面越宽，河水越深，城池也就越安全。如果市场对 UST 的币值没有信心，那么上述流动池中，其他稳定币的数量就会逐渐减少，而 UST 的数量将逐渐增加。</p><p>所以，Curve 中 UST 相关流动池的锁仓资金量，对于 UST 的币值稳定不仅是非常重要的，甚至可以说是决定性的。但这些信息却又都是公开透明、所有人可见的，这种公开透明就在客观上为市场上的空头，提供了一种可以利用的机会。</p><p>要知道，在一般情况下，市场对 UST 币值的稳定越有信心，则参与提供流动性挖矿的锁仓资金量就越大，这些资金的 TVL 甚至可以看成是稳定币币价的基本面。但在极端的情况下，流动池 TVL 又会成为在市场上引起连锁反应的导火索。</p><p>假如因为技术原因或者其他偶然因素，这个 TVL 发生了剧烈变化，即使是短暂的剧烈变化，如果被市场空头所利用，并在价格上引起快速波动的话，不仅会对市场发出错误的价格信号，同时也会通过以 Curve 报价作为价格输出的预言机，传导给其他 DeFi 协议，比如抵押借贷协议，并造成一系列的连锁反应。</p><p>当市场空头利用稳定币的锁仓资金量快速下跌的时机，大量抛售稳定币，那么稳定币在 Curve的短时报价，就会大大低于锚定价格。这时候，DeFi 中的抵押借贷协议就会根据这个价格信号开始清算。</p><p>而我们也清楚，中心化的抵押借贷平台虽然不是基于智能合约执行清算的，但对于清算条件的设置也和抵押借贷协议大体相似，如果短期内稳定币的价格不能迅速恢复正常，那么中心化借贷平台也会开始启动清算，大规模清算一旦启动，稳定币将在市场上被大量抛售，并可能形成价格踩踏。</p><h3 id="稳定币基本面的重要性" tabindex="-1">稳定币基本面的重要性 <a class="header-anchor" href="#稳定币基本面的重要性" aria-label="Permalink to &quot;稳定币基本面的重要性&quot;">​</a></h3><p>这时候，发挥关键作用的就应该是稳定币的基本面了，如果市场认为稳定币项目的基本面还可以，有望最终稳住价格，那市场上就会有抄底资金介入，帮助币价稳定；但如果市场认为稳定币的价格缺乏支撑，那么币价就很难恢复到稳定水平。这样，本来是非市场原因造成的价格波动，最后在事实上就演变成了一次市场的出清。</p><p>Terra 的经历正好验证了上述推断。就在 Terra 团队开始流动性调仓的时候，有机构开始大量卖出 UST，UST 随之开始脱锚。</p><p>而 UST 一旦脱锚，在前面我们介绍的套利机制的作用下，用户的反应就是卖出 UST 换成LUNA。如果 LUNA 的价格可以保持稳定或者回升，用户的操作也就到此为止了。但是市场并没有为 LUNA 提供这样的一个机会，BTC 都在连续回调，LUNA 更不可能独善其身。</p><p>由此一来，LUNA 价格持续下跌，导致用户卖出 LUNA，这时候 LUNA 已经不再能承担 UST价值稳定的作用了，而是成为了 UST 价格继续下滑的催化剂，这就是所谓的“死亡螺旋”。</p><p>从 2022 年 5 月 8 日开始到 5 月 28 日，UST 市值从 187 亿美元跌到 2 亿，LUNA 市值从265 亿美元跌到 6 亿。在 LUNA 身上，我们见证了加密资产市场涨跌幅度和速度最快的演变，但无论如何，UST 作为一个稳定币确实是崩盘了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web3.0%E5%85%A5%E5%B1%80%E6%94%BB%E7%95%A5/images/12-DeFi%25E7%259A%2584%25E7%25A9%25BA%25E4%25B8%25AD%25E6%25A5%25BC%25E9%2598%2581%25E8%2583%25BD%25E7%259B%2596%25E5%25A4%259A%25E9%25AB%2598%25EF%25BC%259F/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web3.0%E5%85%A5%E5%B1%80%E6%94%BB%E7%95%A5/images/12-DeFi%25E7%259A%2584%25E7%25A9%25BA%25E4%25B8%25AD%25E6%25A5%25BC%25E9%2598%2581%25E8%2583%25BD%25E7%259B%2596%25E5%25A4%259A%25E9%25AB%2598%25EF%25BC%259F/2.png" alt=""></a></p><ul><li>截至5月19日LUNA价格图片截取自CoinMarketCap（加密资产价格跟踪网站）</li></ul><p>好了，通过 UST 的案例我们可以看出，抵押借贷作为一种具备一定杠杆效应的金融工具，通过 DeFi 协议之间的可组合性，已经给不同资产之间的价格风险建立起了一种联系，由于这种联系是基于智能合约实现的，所以也具有高度的灵敏性和扩散性。而加密市场各种资产价格上的强一致性，如比特币的涨跌，往往会带动大部分资产价格发生同方向上的调整，这种强一致性，又进一步放大了这种“抵押借贷”带来的扩散效应。</p><p>所以说，抵押借贷已经成为一种具有较强系统性风险的业务。对于我们用户而言，使用抵押借贷一定要关注这方面的风险，如果是出于对冲风险的目的而使用抵押借贷，则一定要控制好时间期限，参与抵押借贷的时间越长，可能承受的系统性风险越大。</p><h2 id="流动性挖矿的风险" tabindex="-1">流动性挖矿的风险 <a class="header-anchor" href="#流动性挖矿的风险" aria-label="Permalink to &quot;流动性挖矿的风险&quot;">​</a></h2><p>下面，我们再来看看流动性挖矿的相关风险。流动性挖矿的原理，在前面讲 DeFi 的时候已经说明过了，这里就不再详述。在这里，我们主要强调的是参与流动性挖矿的收益风险问题，以及为了争夺流动性挖矿奖励而产生的多层嵌套问题。</p><h3 id="流动性挖矿的收益风险问题" tabindex="-1">流动性挖矿的收益风险问题 <a class="header-anchor" href="#流动性挖矿的收益风险问题" aria-label="Permalink to &quot;流动性挖矿的收益风险问题&quot;">​</a></h3><p>我们先来看流动性挖矿的收益风险问题。</p><p>首先，流动性挖矿可能会获得两种奖励：一种是手续费分成，但手续费分成需要按照你提供的资金量去分配手续费，对于资金量不大的用户，其实收益也非常有限；另外一种是去中心化交易所平台币的奖励，这种奖励虽然也是根据你提供的资金量进行分配的，但是奖励的年化收益率可能会很高，年化上百甚至数百的项目非常普遍，所以很多用户冲着这种高收益，就投入了自己的资金。但是一段时间之后，挖矿收益却少得可怜，甚至本金也无法收回。</p><p>为什么出现这种情况呢？因为流动性挖矿的预期收益率，是按照奖励代币的实时价格计算的。在产品上线初期，挖矿奖励产出少，流动性挖矿又需要两种代币配对（ETH 和 USDT），所以奖励代币价格高，流动挖矿收益率也高，大量用户参与挖矿，就导致奖励代币价格和挖矿收益率形成了一种相互加强的正循环，从而导致年化收益率达到了一种“离谱”的高度。</p><p>但是，这种正向循环一定是不可持续的，一旦流量增长遇到拐点，用户快速抛售挖矿奖励所得资产就会导致其价格加速下跌，不仅预期的高收益不再存在，而且本金都有可能损失。</p><p>你可能会问，为什么还会造成本金损失呢？这是因为，流动性挖矿需要两种代币配对，当你只有 ETH 或者 USDT 的时候，你需要买进另外一种代币组成 LP Token，才能参与流动性挖矿。</p><p>在挖矿初期，这种“配对”需求就造成代币价格大涨，挖矿收益率也达到了一个很高的数值，但当流量反转的时候，不仅挖矿收益率大跌，代币本身的价格也大跌，当你准备退出挖矿而卖出代币的时候，大概率情况下本金是无法回收的，所以本金也可能损失。</p><h3 id="为争夺流动性挖矿奖励产生的多层嵌套问题" tabindex="-1">为争夺流动性挖矿奖励产生的多层嵌套问题 <a class="header-anchor" href="#为争夺流动性挖矿奖励产生的多层嵌套问题" aria-label="Permalink to &quot;为争夺流动性挖矿奖励产生的多层嵌套问题&quot;">​</a></h3><p>然后我们再来看看为了争夺流动性挖矿收益，而产生的多层嵌套问题，这个问题主要是因为Curve 产生的。</p><p>前面我们也简单介绍过，Curve 是一个主要针对“类似资产”，提供低滑点交易的去中心化交易协议，“类似资产”指的是具有相同价格锚定对象的资产，比如与美元挂钩的各种稳定币。</p><p>我们在前面 DEX 一节曾经提到过，AMM 模式最大的缺陷在于无常损失，而无常损失的大小，又只和价格波动幅度相关联，“类似资产”之间是所有资产中价格波动最小的交易对。所以，Curve 通过一种“舍得”的方式，找到了最适合 AMM 发挥作用的场景。</p><p>我们在前面提到过，对于各种稳定币来说，在 Curve 设立流动池是其体现币值稳定的必要条件。所以，在 Curve 整合 USDC、USDT 和 DAI 创建的三币池的基础上，组建“X+CRV3”的四币池，就成为了众多稳定币创建流动性的标配。</p><p>但是创建流动池，需要添加流动性，仅仅依靠项目方自己添加显然是不够的。于是，吸引用户添加流动性就成为各个稳定币的基本动作。</p><p>那么，如何吸引用户添加流动性呢？激励方法只有流动性挖矿，每一个稳定币要想获得更多的流动性，就看这个稳定币能不能在 Curve 池提供更具竞争力的奖励。Curve 推出按照时间加权分配 CRV（币池）的方案，正好为各个稳定币激励竞争提供了一个良好的舞台，由此 CurveWar 拉开了序幕！</p><p>在 Curve War 中，最主要的就是两个选手，一个是 Yearn，另外一个是 Convex。</p><p>其中，Convex 的方法是把 CRV 作为流动性激励和治理投票的功能，拆分成了 cvxCRV 和vlCVX，使 CRV 持有者既可以获得流动性奖励，又可以参与社区治理。基于这个功能，Convex 不仅取得了 Curve War 大战的胜利，甚至 Yearn 也将其收集的 LP 转投 Convex。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web3.0%E5%85%A5%E5%B1%80%E6%94%BB%E7%95%A5/images/12-DeFi%25E7%259A%2584%25E7%25A9%25BA%25E4%25B8%25AD%25E6%25A5%25BC%25E9%2598%2581%25E8%2583%25BD%25E7%259B%2596%25E5%25A4%259A%25E9%25AB%2598%25EF%25BC%259F/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web3.0%E5%85%A5%E5%B1%80%E6%94%BB%E7%95%A5/images/12-DeFi%25E7%259A%2584%25E7%25A9%25BA%25E4%25B8%25AD%25E6%25A5%25BC%25E9%2598%2581%25E8%2583%25BD%25E7%259B%2596%25E5%25A4%259A%25E9%25AB%2598%25EF%25BC%259F/3.png" alt=""></a></p><ul><li>Converting CRV + Staking cvxCRV来源于Convex Finance</li></ul><p>由此一来，在 Convex 已经掌握了半数以上 CRV 的情况下，稳定币项目方就不再尝试购买CRV 质押投票，而是转向购买 CVX。但购买 CVX 然后锁定为 vlCVX，再参与治理投票，这个过程不仅麻烦，而且还会让持有人面临新的价格风险，于是一种走捷径的“贿赂网站”应运而生。</p><p>既然稳定币最需要的是 CVX 的投票权，而非 CVX 本身，那么我们就创造一个平台，在这个平台上，稳定币项目方可以为 CVX 持有人提供一些奖励，以换取 CVX 的投票权。所以，这种网站有了一个形象的名字，就是“贿赂网站”。</p><p>比如，有一个协议 Redacted Cartel 通过分叉 Olympus 的 Bonding 机制，建立了一个基于治理代币 BTRFLY 收集投票权资产的机制，之后再通过拍卖投票权获得收益，并在 BTRFLY持有人之间进行分配。</p><p>那么，从 Redacted Cartel 的方案来看，所谓的“流动性管理创新”，好像就是没有止境地叠加，就是不断地用新的代币去收集原来具有投票权的资产，从而将投票权转移到新的资产上面。这就像一座空中楼阁一样，不断叠加、不断长高，但是却因为没有地基而随时可能坍塌。</p><p>所以我们要知道，尽管 DeFi 的各种协议通过组合的方式，可以创造出很多复杂的功能，但是没有充足的可以创造基础收益的底层资产作为支撑，DeFi 的价值又有多大呢？</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这节课，我们通过 LUNA 的案例，看到了抵押借贷对于价格风险的巨大的扩散性，这个对于使用抵押借贷对冲风险的用户来说，需要特别关注。</p><p>另外，我也带你分析了流动性挖矿所谓超高收益的主要来源，并发现这种收益的不可持续性，以及可能对本金造成的损失。而且我们还发现，虽然代币激励对于用户参与流动性挖矿，具有一定的积极效应，但过度嵌套无异于将 DeFi 变成了一座空中楼阁，同样也会加大系统性风险。</p><p>下节课，我们还会针对法律和伦理方面的风险来进行探讨，我们不见不散。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>在你关注到的 DeFi 项目中，还有哪些比较隐蔽的风险？你是怎么看待这种风险的？欢迎在留言区分享你的看法和思考。另外，也欢迎你把今天的内容分享给更多的朋友。</p>',75)])])}const T=a(r,[["render",l]]);export{u as __pageData,T as default};
